'use client';

import {
  Toc as TocPrimitive,
  type UseTocProps,
  useToc as useTocPrimitive,
  useTocContext as useTocContextPrimitive,
} from '@ark-ui/react/toc';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import styles from './Toc.module.css';

const railStep = 12;
const railBridge = 6;

// Depths 2 to 4 get their own rail column; deeper headings stay on the last one.
const getRailX = (depth: number) => Math.min(Math.max(depth - 2, 0), 2) * railStep + 0.5;

const useToc = ({ autoScroll = false, ...props }: UseTocProps) =>
  useTocPrimitive({ autoScroll, ...props });

const useTocContext = useTocContextPrimitive;

const Toc = forwardRef<
  ComponentRef<typeof TocPrimitive.Root>,
  ComponentProps<typeof TocPrimitive.Root>
>(function Toc({ autoScroll = false, className, ...props }, ref) {
  return (
    <TocPrimitive.Root
      ref={ref}
      autoScroll={autoScroll}
      className={clsx(styles.root, className)}
      {...props}
      data-slot="toc-root"
    />
  );
});

const TocRootProvider = forwardRef<
  ComponentRef<typeof TocPrimitive.RootProvider>,
  ComponentProps<typeof TocPrimitive.RootProvider>
>(function TocRootProvider({ className, style, value, ...props }, ref) {
  const rootProps = value.getRootProps();

  return (
    <TocPrimitive.RootProvider
      ref={ref}
      value={value}
      {...rootProps}
      className={clsx(styles.root, className)}
      style={{ ...rootProps.style, ...style }}
      {...props}
      data-slot="toc-root-provider"
    />
  );
});

const TocContent = forwardRef<
  ComponentRef<typeof TocPrimitive.Content>,
  ComponentProps<typeof TocPrimitive.Content>
>(function TocContent({ className, ...props }, ref) {
  return (
    <TocPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="toc-content"
    />
  );
});

const TocNav = forwardRef<
  ComponentRef<typeof TocPrimitive.Nav>,
  ComponentProps<typeof TocPrimitive.Nav>
>(function TocNav({ className, ...props }, ref) {
  return (
    <TocPrimitive.Nav
      ref={ref}
      className={clsx(styles.nav, className)}
      {...props}
      data-slot="toc-nav"
    />
  );
});

const TocTitle = forwardRef<
  ComponentRef<typeof TocPrimitive.Title>,
  ComponentProps<typeof TocPrimitive.Title>
>(function TocTitle({ className, ...props }, ref) {
  return (
    <TocPrimitive.Title
      ref={ref}
      className={clsx(styles.title, className)}
      {...props}
      data-slot="toc-title"
    />
  );
});

const TocList = forwardRef<
  ComponentRef<typeof TocPrimitive.List>,
  ComponentProps<typeof TocPrimitive.List>
>(function TocList({ className, ...props }, ref) {
  return (
    <TocPrimitive.List
      ref={ref}
      className={clsx(styles.list, className)}
      {...props}
      data-slot="toc-list"
    />
  );
});

const TocItem = forwardRef<
  ComponentRef<typeof TocPrimitive.Item>,
  ComponentProps<typeof TocPrimitive.Item>
>(function TocItem({ className, ...props }, ref) {
  return (
    <TocPrimitive.Item
      ref={ref}
      className={clsx(styles.item, className)}
      {...props}
      data-slot="toc-item"
    />
  );
});

const TocLink = forwardRef<
  ComponentRef<typeof TocPrimitive.Link>,
  ComponentProps<typeof TocPrimitive.Link>
>(function TocLink({ className, ...props }, ref) {
  return (
    <TocPrimitive.Link
      ref={ref}
      className={clsx(styles.link, className)}
      {...props}
      data-slot="toc-link"
    />
  );
});

const TocIndicator = forwardRef<
  ComponentRef<typeof TocPrimitive.Indicator>,
  ComponentProps<typeof TocPrimitive.Indicator>
>(function TocIndicator({ className, ...props }, ref) {
  return (
    <TocPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="toc-indicator"
    />
  );
});

type TocRailProps = ComponentProps<'svg'> & {
  depth: number;
  previousDepth?: number;
  nextDepth?: number;
};

const TocRail = forwardRef<SVGSVGElement, TocRailProps>(function TocRail(
  { className, depth, nextDepth = depth, previousDepth = depth, style, ...props },
  ref,
) {
  const x = getRailX(depth);
  const previousX = getRailX(previousDepth);
  const nextX = getRailX(nextDepth);
  const hasTurn = previousX !== x;

  return (
    <svg
      ref={ref}
      aria-hidden="true"
      className={clsx(styles.rail, className)}
      style={{
        width: Math.max(previousX, x, nextX) + 1.5,
        // Cross the list gap to the next rail, and its bridge too when the line continues.
        height: `calc(100% + ${nextX === x ? railBridge : 0}px + var(--moduix-spacing-0-5))`,
        ...style,
      }}
      {...props}
      data-slot="toc-rail"
    >
      {hasTurn && (
        <path
          d={`M ${previousX} 0 C ${previousX} 8 ${x} 4 ${x} ${railBridge * 2}`}
          fill="none"
          vectorEffect="non-scaling-stroke"
          stroke="currentColor"
        />
      )}
      <line
        x1={x}
        y1={hasTurn ? railBridge * 2 : railBridge}
        x2={x}
        y2="100%"
        vectorEffect="non-scaling-stroke"
        stroke="currentColor"
      />
    </svg>
  );
});

const TocContext = TocPrimitive.Context;

export {
  Toc,
  TocContext,
  TocContent,
  TocIndicator,
  TocItem,
  TocLink,
  TocList,
  TocNav,
  TocRail,
  TocRootProvider,
  TocTitle,
  useToc,
  useTocContext,
};

export type {
  TocActiveChangeDetails,
  TocContentProps,
  TocContextProps,
  TocIndicatorProps,
  TocItemData,
  TocItemProps,
  TocLinkProps,
  TocListProps,
  TocNavProps,
  TocRootProps,
  TocRootProviderProps,
  TocTitleProps,
  UseTocContext,
  UseTocProps,
  UseTocReturn,
} from '@ark-ui/react/toc';
export type { TocRailProps };

@layer moduix.components {
  .root {
    display: grid;
    width: 100%;
    min-width: 0;
    grid-template-columns: minmax(0, 1fr) minmax(12rem, 16rem);
    gap: var(--moduix-spacing-6);
    color: var(--moduix-color-foreground);
    /* Read Ark measurements here: parents of the list, such as Collapsible, redefine --top and --height. */
    --_toc-indicator-top: var(--top);
    --_toc-indicator-height: var(--height);

    &:has(.nav[data-placement='left']) {
      grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);
    }

    @media (width < 48rem) {
      &,
      &:has(.nav[data-placement='left']) {
        grid-template-columns: minmax(0, 1fr);
      }
    }
  }

  .content {
    min-width: 0;
  }

  .nav {
    position: sticky;
    top: var(--moduix-spacing-4);
    align-self: start;
    max-height: calc(100dvh - 2rem);
    overflow: auto;
    padding: var(--moduix-spacing-4);
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-radius-lg);
    background-color: var(--moduix-color-card);
    color: var(--moduix-color-card-foreground);

    /* The content takes the next free cell, so only the nav needs explicit placement. */
    &[data-placement='left'] {
      grid-row: 1;
      grid-column: 1;

      @media (width < 48rem) {
        grid-area: auto;
      }
    }
  }

  .title {
    margin: 0 0 var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-semibold);
    line-height: var(--moduix-line-height-text-sm);
  }

  .list {
    position: relative;
    display: grid;
    gap: var(--moduix-spacing-0-5);
    margin: 0;
    padding-inline-start: var(--moduix-spacing-1);
    list-style: none;

    &:has(.indicator)::before {
      position: absolute;
      top: var(--moduix-spacing-0-5);
      bottom: var(--moduix-spacing-0-5);
      inset-inline-start: 0;
      width: var(--moduix-border-width-md);
      border-radius: var(--moduix-radius-full);
      background-color: var(--moduix-color-border);
      content: '';
      pointer-events: none;
    }
  }

  .item {
    min-width: 0;
  }

  .link {
    position: relative;
    display: block;
    padding-block: var(--moduix-spacing-1);
    padding-inline-end: var(--moduix-spacing-1);
    padding-inline-start: calc(
      var(--moduix-spacing-1) + var(--moduix-border-width-md) + var(--moduix-spacing-2) +
        max(0px, calc((var(--depth) - 2) * var(--moduix-spacing-2)))
    );
    /* Clip only horizontally so TocRail can reach the neighbouring items. */
    overflow-x: clip;
    border-radius: var(--moduix-radius-sm);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    text-decoration: none;
    text-overflow: ellipsis;
    white-space: nowrap;
    outline: none;
    transition: color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        color: var(--moduix-color-foreground);
      }
    }

    &:focus-visible {
      box-shadow: 0 0 0 var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        var(--moduix-color-ring);
    }

    &[data-active] {
      color: var(--moduix-color-foreground);
      font-weight: var(--moduix-weight-medium);

      .rail {
        color: var(--moduix-color-muted-foreground);
        opacity: 0.7;
        translate: 0 var(--moduix-spacing-0-5);
      }
    }
  }

  .indicator {
    z-index: 1;
    top: calc(var(--_toc-indicator-top) + var(--moduix-spacing-0-5));
    inset-inline-start: 0;
    width: var(--moduix-border-width-md);
    height: calc(var(--_toc-indicator-height) - var(--moduix-spacing-1));
    border-radius: var(--moduix-radius-full);
    background-color: var(--moduix-color-muted-foreground);
    opacity: 0.7;
    pointer-events: none;
    transition:
      top var(--moduix-transition-default),
      height var(--moduix-transition-default);
  }

  .rail {
    position: absolute;
    top: calc(-1 * var(--moduix-spacing-1-5));
    inset-inline-start: 0;
    overflow: visible;
    color: var(--moduix-color-border);
    pointer-events: none;

    & :is(line, path) {
      stroke-width: var(--moduix-border-width-sm);
    }
  }
}
